function mensaje_resp(e, n) {
  $("#message").html(
    `<div class="alert alert-${e}"><a href="#" class="close" data-dismiss="alert">&times;</a><strong> ${n}</strong></div>`
  );
}

function direccion(e) {
  sessionStorage.setItem("_TOKEN", e.Token);
  sessionStorage.setItem("Nombre", e.NombreUsuario);
  sessionStorage.setItem("Rol", e.Rol_Id);
  sessionStorage.setItem("linlin", e.Id_Usuario);  
  sessionStorage.setItem("COWBY", e.Cuenta_Id);  
  sessionStorage.setItem("CXC", e.Conexion_Id); 
  (window.location = "main.html");
}

function generateToken(e) {
  for (
    var n = "#@abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_",
      o = "",
      t = 0;
    t < e;
    t++
  )
    o += n[Math.floor(Math.random() * n.length)];
  return o;
}

async function getConfig(){
  paramURL = await geturlM();
  await variablesEntorno(paramURL.urlConfig);  
}

function geturlM(){ 
  return new Promise((resolve, reject) => {
    try {
      var file = new XMLHttpRequest();
      var fileRuta = 'assets\\js\\general\\config.json'
      file.open("GET",fileRuta,false);
      file.send(null);
      var conf = JSON.parse(file.responseText);
      resolve(conf)      
    } catch (error) {
      log.error(String(err).red)
      reject(String(err).red)
    }
  })        
}

function variablesEntorno(wsu){ 
  return new Promise((resolve, reject) => {
    try {
      $.ajax({
        url: wsu + "/api/Configuracion/ConfiguracionIniCON",
        type: 'POST',
        contentType: 'application/json',
        data: JSON.stringify({}),
        beforeSend: function(a){
               $('html, body').animate({scrollTop: 0}, 'slow');
               //$("#DivLoading").show();
             },
        success: function(data){
              
              if (data.Respuesta.length > 0){
                for (row in data.Respuesta){
                  const Variable = data.Respuesta[row].Variable
                  const Valor = data.Respuesta[row].Valor
                  sessionStorage.setItem(Variable, Valor);                
                }
              }
              if (sessionStorage.pathWs){
                sessionStorage.pathWs = wsu;
              }else{
                sessionStorage.setItem("pathWs", wsu);
              }
              
              resolve(true)
             },
        error: function(a,b,c){
              console.log('Error: '+a+'\n'+b+'\n'+c);
              reject(false)
             },
        complete:function(){

        }
      });
      
    } catch (error) {
      console.log(error)
      reject(false)
    }
  })        
}

