$(function () {  
  getConfig();
  sessionStorage.removeItem("_TOKEN"),
  sessionStorage.clear(),
  $("#nombreu, #contrasenia").keypress(function (e) {
    13 == e.which && $("#loginButton").trigger("click");
  }),
  $("#loginButton").click(function () {
    if (
      "" === $("#nombreu").val().trim() ||
      "" === $("#contrasenia").val().trim()
    )
      return void mensaje_resp("warning", "Error datos incorrectos");
    $("#Token").val(generateToken(40));
    const e = document.getElementById("contrasenia").value;
    var n = CryptoJS.MD5(e).toString();
    document.getElementById("contrasenia").value = n;
      $.ajax({
        headers: { 
          'Accept': 'application/json',
          'Content-Type': 'application/json' 
        },
        data: JSON.stringify({Token:$("#Token").val(),Cuenta:$("#nombreu").val(),Pwd:n,Expira:((new Date() / 1e3) | 0) + TimeOutMain}),
        type: "post",
        dataType: "json",
        url: `${sessionStorage.pathWs}/api/Portal/UsuarioLogin`,
        beforeSend: function (data) {},
        success: function (data) {
          if (data.Respuesta[0].Token)
          {
            mensaje_resp("success", "Usuario registrado")
            direccion(data.Respuesta[0])
            $("html, body").animate({ scrollTop: 0 }, "slow")
            $("#loginButton").html("Entrar")
          }else{
            $("#box-login").trigger("reset")
            mensaje_resp("danger", "Error con las credenciales")
            $("html, body").animate({ scrollTop: 0 }, "slow")
            $("#loginButton").html("Entrar")
          }

        },
        error: function (data) {
          console.log("Error =>", e);
        },
      });
  });
});
